import sys

class MedianBrute:
    def __init__(self):
        self.nums = []
    def addNum(self, x):
        self.nums.append(x)
    def findMedian(self):
        s = sorted(self.nums)
        n = len(s)
        if n % 2 == 1:
            return float(s[n // 2])
        return (s[n // 2 - 1] + s[n // 2]) / 2.0

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    q = int(data[0])
    m = MedianBrute()
    i = 1
    while q > 0 and i < len(data):
        if data[i] == 'addNum':
            m.addNum(int(data[i + 1]))
            i += 2
        else:
            print('%.1f' % m.findMedian())
            i += 1
        q -= 1

import sys
import bisect

class MedianOpt:
    def __init__(self):
        self.nums = []
    def addNum(self, x):
        bisect.insort(self.nums, x)
    def findMedian(self):
        n = len(self.nums)
        mid = n // 2
        if n % 2 == 1:
            return float(self.nums[mid])
        return (self.nums[mid - 1] + self.nums[mid]) / 2.0

